#!/usr/bin/env node
/**
 * THE CONTROL-RULE FIELD LIST IS GENERATED FROM THE SERVER'S PYDANTIC MODEL.
 *
 * Why: the admin Controls editor (features/ai-models) validated stored rules
 * against a hand-written copy of `matrx_ai.catalog.models.ControlRule`'s field
 * list. The copy had already lost `to_default`, so a valid server field was
 * flagged "unknown" — and the settings-translation rule language (contract K6,
 * common-docs/projects/settings-translation/CONTRACTS.md) is adding more. A copy
 * drifts; a generated file plus a check that refuses drift does not.
 *
 * What it writes: features/ai-models/controls/controlRuleFields.generated.ts
 *   SERVER_RULE_FIELDS   — exactly `ControlRule.model_fields`, in declaration
 *                          order, read by importing the model from ../aidream.
 *   CONTRACT_RULE_FIELDS — K6 fields the frozen contract adds that the server
 *                          model does not define yet. As soon as the server
 *                          grows one, it moves to SERVER_RULE_FIELDS on the
 *                          next generation (and the check goes red until then).
 *   RULE_FIELDS          — both, the list every frontend reader uses.
 *
 * Usage:
 *   node scripts/control-rule-fields.mjs --write      # regenerate the committed file
 *   node scripts/control-rule-fields.mjs --check      # RED (exit 1) when the committed file is stale
 *   node scripts/control-rule-fields.mjs --self-test  # proves --check goes red on a planted mismatch
 *   node scripts/control-rule-fields.mjs --check --committed <file>   # judge a copy
 *
 * Exit 0 = fresh. Exit 1 = drift. Exit 2 = UNMEASURED (no aidream checkout or
 * no `uv`) — never a pass.
 */

import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, "..");
const AIDREAM_ROOT = resolve(REPO_ROOT, "../aidream");
export const OUTPUT = resolve(
  REPO_ROOT,
  "features/ai-models/controls/controlRuleFields.generated.ts",
);

/** Contract K6 (frozen, settings-translation CONTRACTS.md): rule-level fields
 *  the server model gains. `drop` + `why` are the declared-drop form
 *  `{"drop": true, "why": ...}`. Listed here ONLY until the server defines
 *  them; the generator never emits a field twice. */
export const K6_CONTRACT_FIELDS = [
  "off",
  "from_number",
  "to_number",
  "accepts",
  "drop",
  "why",
];

const PY = [
  "import json",
  "from matrx_ai.catalog.models import ControlRule",
  "print(json.dumps(list(ControlRule.model_fields.keys())))",
].join("\n");

function unmeasured(message) {
  const err = new Error(message);
  err.exitCode = 2;
  throw err;
}

/** Read the field names of the server's ControlRule, in declaration order. */
export function readServerFields(aidreamRoot = AIDREAM_ROOT) {
  if (!existsSync(aidreamRoot)) {
    unmeasured(`UNMEASURED: no aidream checkout at ${aidreamRoot} — it IS the model this file mirrors.`);
  }
  let out;
  try {
    out = execFileSync("uv", ["run", "--quiet", "python", "-c", PY], {
      cwd: aidreamRoot,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
      timeout: 180_000,
    });
  } catch (e) {
    unmeasured(
      `UNMEASURED: could not import matrx_ai.catalog.models.ControlRule in ${aidreamRoot} (${e.message.split("\n")[0]}).\n` +
        `Reproduce: cd ${aidreamRoot} && uv run python -c "from matrx_ai.catalog.models import ControlRule; print(list(ControlRule.model_fields))"`,
    );
  }
  const fields = JSON.parse(out.trim().split("\n").pop());
  if (!Array.isArray(fields) || fields.length === 0) {
    unmeasured("UNMEASURED: ControlRule reported no fields.");
  }
  return fields;
}

export function render(serverFields) {
  const contract = K6_CONTRACT_FIELDS.filter((f) => !serverFields.includes(f));
  const list = (xs) => xs.map((f) => `  "${f}",`).join("\n");
  return `// GENERATED by scripts/control-rule-fields.mjs — never hand-edit.
// Source: aidream matrx_ai.catalog.models.ControlRule.model_fields (+ contract K6).
// Regenerate: node scripts/control-rule-fields.mjs --write
// Guard:      pnpm check:control-rule-fields

/** Fields the server's ControlRule model defines today, in declaration order. */
export const SERVER_RULE_FIELDS = [
${list(serverFields)}
] as const;

/** Contract K6 fields the server model does not define yet. */
export const CONTRACT_RULE_FIELDS = [
${contract.length ? list(contract) + "\n" : ""}] as const;

/** Every valid ControlRule field — what frontend readers accept. */
export const RULE_FIELDS = [...SERVER_RULE_FIELDS, ...CONTRACT_RULE_FIELDS] as const;

export type RuleField = (typeof RULE_FIELDS)[number];
`;
}

/** Compare a committed file with the reference text. Returns issue lines. */
export function compare(committedText, referenceText) {
  if (committedText === referenceText) return [];
  const a = committedText.split("\n");
  const b = referenceText.split("\n");
  const issues = [];
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    if (a[i] !== b[i]) issues.push(`  line ${i + 1}: committed ${JSON.stringify(a[i] ?? "")} ≠ generated ${JSON.stringify(b[i] ?? "")}`);
    if (issues.length >= 10) break;
  }
  return issues;
}

function check(committedPath, serverFields) {
  if (!existsSync(committedPath)) {
    console.error(`DRIFT: ${committedPath} is missing. Run: node scripts/control-rule-fields.mjs --write`);
    return 1;
  }
  const issues = compare(readFileSync(committedPath, "utf8"), render(serverFields));
  if (issues.length) {
    console.error(
      `DRIFT: ${committedPath} does not match the server's ControlRule model.\n${issues.join("\n")}\n` +
        "Remedy: node scripts/control-rule-fields.mjs --write  (then check the editor/validator for the new field).",
    );
    return 1;
  }
  console.log(`OK: control-rule fields match the server model (${serverFields.length} server + contract fields).`);
  return 0;
}

function selfTest() {
  const server = readServerFields();
  const dir = mkdtempSync(join(tmpdir(), "control-rule-fields-"));
  let failed = 0;
  try {
    const good = join(dir, "good.ts");
    writeFileSync(good, render(server));
    if (check(good, server) !== 0) {
      console.error("SELF-TEST FAIL: a freshly generated file was judged stale.");
      failed++;
    }
    // Plant 1: the committed file lost a server field (the to_default class).
    const lost = join(dir, "lost.ts");
    writeFileSync(lost, render(server.filter((f) => f !== server[2])));
    if (check(lost, server) !== 1) {
      console.error("SELF-TEST FAIL: a file missing a server field passed.");
      failed++;
    }
    // Plant 2: the server grew a field the committed file does not know.
    const grown = join(dir, "grown.ts");
    writeFileSync(grown, render(server));
    if (check(grown, [...server, "planted_new_server_field"]) !== 1) {
      console.error("SELF-TEST FAIL: a server field missing from the committed file passed.");
      failed++;
    }
    // Plant 3: a K6 field landed on the server but the file still lists it as contract-only.
    const moved = join(dir, "moved.ts");
    writeFileSync(moved, render(server.filter((f) => f !== "off")));
    if (check(moved, server.includes("off") ? server : [...server, "off"]) !== 1) {
      console.error("SELF-TEST FAIL: a K6 field moving onto the server went unseen.");
      failed++;
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
  if (failed) return 1;
  console.log("SELF-TEST OK: --check is green on a fresh file and red on 3 planted mismatches.");
  return 0;
}

function main(argv) {
  const committedIdx = argv.indexOf("--committed");
  const committed = committedIdx >= 0 ? resolve(argv[committedIdx + 1]) : OUTPUT;
  if (argv.includes("--self-test")) return selfTest();
  const server = readServerFields();
  if (argv.includes("--write")) {
    writeFileSync(OUTPUT, render(server));
    console.log(`Wrote ${OUTPUT} (${server.length} server fields).`);
    return 0;
  }
  return check(committed, server);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    process.exit(main(process.argv.slice(2)));
  } catch (e) {
    console.error(e.message);
    process.exit(e.exitCode ?? 1);
  }
}
